		char[] chars = CachedCharArray.getCharArray(charCount);
		int c, charIndex = 0;
		while (charIndex < charCount) {
			c = readByte() & 0xff;
			switch (c >> 4) {
			case 0:
			case 1:
			case 2:
			case 3:
			case 4:
			case 5:
			case 6:
			case 7:
				chars[charIndex++] = (char) c;
				break;
			case 12:
			case 13:
				chars[charIndex++] = (char) ((c & 0x1F) << 6 | readByte() & 0x3F);
				break;
			case 14:
