	public Object readGenericValue() throws IOException {
		byte type = readByte();
		switch (type) {
		case -1:
			return null;
		case 0:
			return readString();
		case 1:
			return readInt();
		case 2:
			return readLong();
		case 3:
			return readFloat();
		case 4:
			return readDouble();
		case 5:
			return readBoolean();
		case 6:
			int bytesSize = readVInt();
			byte[] value = new byte[bytesSize];
			readBytes(value, 0, bytesSize);
			return value;
		case 7:
			int size = readVInt();
			List<Object> list = new ArrayList<>(size);
			for (int i = 0; i < size; i++) {
				list.add(readGenericValue());
			}
			return list;
		case 8:
			int size8 = readVInt();
			Object[] list8 = new Object[size8];
			for (int i = 0; i < size8; i++) {
				list8[i] = readGenericValue();
			}
			return list8;
		case 9:
			int size9 = readVInt();
			Map<String, Object> map9 = new LinkedHashMap<>(size9);
			for (int i = 0; i < size9; i++) {
				map9.put(readString(), readGenericValue());
			}
			return map9;
		case 10:
			int size10 = readVInt();
			Map<String, Object> map10 = new HashMap<>(size10);
			for (int i = 0; i < size10; i++) {
				map10.put(readString(), readGenericValue());
			}
			return map10;
		case 11:
			return readByte();
		case 12:
			return new Date(readLong());
		case 14:
			int size14 = readVInt();
			BytesBuffer b = new BytesBuffer(size14);
			readBytes(b);
			return b;
		case 16:
			return readShort();
		default:
			throw new IOException("Can't read unknown type [" + type + "]");
		}
	}

	public void skipVIntData() throws IOException{
		//읽어서 버린다.
		int len = readVInt();
		for (int i = 0; i < len; i++){
			readByte();
		}
	}

    public String readAStrings() throws IOException {
        int len = readVInt();
        char[] cs = new char[len];
        for (int i = 0; i < len; i++) {
			cs[i] = (char) readByte();
		}
        return new String(cs);
    }

	public char[] readAString() throws IOException {
		int len = readVInt();
		char[] cs = new char[len];
		for (int i = 0; i < len; i++) {
			cs[i] = (char) readByte();
		}
		return cs;
	}

	public char[] readUString() throws IOException {
		int byteSize = readVInt();
		char[] cs = new char[byteSize / 2];
		for (int i = 0; i < cs.length; i++) {
			cs[i] = (char) readShort();
		}
		return cs;
	}

	public char readAChar() throws IOException {
		return (char) readByte();
	}

	public char readUChar() throws IOException {
		return (char) readShort();
	}
